const assert = require('node:assert/strict');
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
module.exports = async function checkJourneys({ cdp, base, navigate, screenshot, fixture, results }) {
  const evaluate = expression => cdp.evaluate(`(()=>eval(${JSON.stringify(expression)}))()`);
  async function wait(expression) {
    for (let i = 0; i < 120; i++) { if (await evaluate(expression)) return; await delay(50); }
    throw new Error('Journey condition not met: ' + expression);
  }
  await navigate(base + '/student/index.html?grade=4&modo=demo');
  assert.match(await evaluate(`document.querySelector('.student-guide').textContent`), /no son notas oficiales/);
  await evaluate(`document.querySelector('.student-guide summary').click()`);
  assert.equal(await evaluate(`document.querySelector('.student-guide').open`), true);
  await navigate(base + '/student/ejercicio.html?grade=4&activity=practice-math-4&modo=demo');
  await evaluate(`const input=document.querySelector('#written-answer');input.value='9';input.dispatchEvent(new Event('input',{bubbles:true}))`);
  assert.equal(await evaluate(`document.querySelector('#activity-save-status').dataset.saved`), 'true');
  const resume = await evaluate('location.href');
  await navigate(resume);
  assert.equal(await evaluate(`document.querySelector('#written-answer').value`), '9');
  await screenshot('student-practice-resumed');
  await evaluate(`window.fixtureNativeSet=Storage.prototype.setItem;Storage.prototype.setItem=function(key,value){if(key==='aithron.demo.activities.v1')throw new DOMException('Fixture quota','QuotaExceededError');return window.fixtureNativeSet.call(this,key,value)};window.fixtureConfirm=window.confirm;window.fixtureConfirmCalls=0;window.confirm=()=>{window.fixtureConfirmCalls++;return false};const input=document.querySelector('#written-answer');input.value='7';input.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('.activity-header a').click()`);
  assert.equal(await evaluate('location.pathname'), '/student/ejercicio.html');
  assert.equal(await evaluate('window.fixtureConfirmCalls'), 1);
  assert.equal(await evaluate(`document.querySelector('#activity-save-status').dataset.saved`), 'false');
  assert.equal(await evaluate(`const event=new Event('beforeunload',{cancelable:true});window.dispatchEvent(event);event.defaultPrevented`), true);
  await evaluate(`Storage.prototype.setItem=window.fixtureNativeSet;window.confirm=window.fixtureConfirm;document.querySelector('#written-answer').dispatchEvent(new Event('input',{bubbles:true}))`);
  assert.equal(await evaluate(`document.querySelector('#activity-save-status').dataset.saved`), 'true');
  await evaluate(`document.querySelector('#activity-question').requestSubmit()`);
  await wait(`Boolean(document.querySelector('#retry-answer:not([hidden])'))`);
  assert.match(await evaluate(`document.querySelector('#answer-feedback').textContent`), /resultado es 9/);
  await evaluate(`document.querySelector('#retry-answer').click();const input=document.querySelector('#written-answer');input.value='9';input.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('#activity-question').requestSubmit()`);
  const firstCheck = await evaluate(`JSON.parse(sessionStorage.getItem('aithron.demo.activities.v1')).sessions.find(s=>s.id===new URL(location.href).searchParams.get('run')).records[0].attempts.map(a=>a.correct)`);
  assert.deepEqual(firstCheck, [false, true]);
  results.push({ check: 'first-use-resume-quota-navigation-protection-and-honest-retries', firstCheck, pass: true });

  fixture.state.failCalendar = true;
  await navigate(base + '/student/agenda.html?grade=4&modo=api');
  assert.equal(await evaluate(`Boolean(document.querySelector('[data-retry-learning]'))`), true);
  assert.equal(await evaluate(`document.querySelectorAll('[data-task]').length`), 0);
  fixture.state.failCalendar = false;
  await evaluate(`document.querySelector('[data-retry-learning]').click()`);
  await wait(`Boolean(document.querySelector('[data-task]')) && document.querySelector('#learning-main').getAttribute('aria-busy')==='false'`);
  await evaluate(`document.querySelector('[data-task]').click()`);
  await wait(`Boolean(document.querySelector('dialog[open] textarea'))`);
  assert.equal(await evaluate(`document.querySelector('.topbar-greeting :is(h1,h2)').textContent`), 'Mi agenda');
  assert.equal(await evaluate(`document.querySelectorAll('#learning-content script').length`), 0);
  await evaluate(`window.fixtureConfirm=window.confirm;window.confirm=()=>false;const input=document.querySelector('dialog[open] textarea');input.value='SYNTHETIC_PRIVATE_RESPONSE';input.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('[data-close]').click()`);
  assert.equal(await evaluate(`Boolean(document.querySelector('dialog[open]'))`), true);
  await evaluate(`document.querySelector('dialog[open]').dispatchEvent(new Event('cancel',{cancelable:true}))`);
  assert.equal(await evaluate(`Boolean(document.querySelector('dialog[open]'))`), true);
  await screenshot('student-task-unsaved');
  await cdp.call('Emulation.setDeviceMetricsOverride', { width: 320, height: 900, deviceScaleFactor: 1, mobile: false });
  assert.equal(await evaluate(`document.documentElement.scrollWidth>innerWidth || document.querySelector('dialog').scrollWidth>document.querySelector('dialog').clientWidth`), false);
  await screenshot('student-task-mobile');
  await cdp.call('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
  const locked = await evaluate(`document.querySelector('[data-save]').click();document.querySelector('dialog textarea').readOnly`);
  assert.equal(locked, true);
  await wait(`document.querySelector('[data-notice]')?.textContent==='Borrador guardado en servidor.'`);
  await evaluate(`document.querySelector('[data-submit]').click()`);
  await wait(`document.querySelector('[data-notice]')?.textContent.includes('No se confirmó')`);
  const patches = fixture.state.patchCalls;
  await evaluate(`document.querySelector('[data-submit]').click()`);
  await wait(`document.querySelector('[data-notice]')?.textContent==='Entrega ya recibida por el servidor.'`);
  assert.equal(fixture.state.submitCalls, 1);
  assert.equal(fixture.state.patchCalls, patches);
  assert.ok(fixture.state.keys[0]);
  assert.equal(await evaluate(`document.querySelector('[data-submit]').disabled`), true);
  assert.equal(await evaluate(`[localStorage,sessionStorage].some(storage=>Object.keys(storage).some(key=>(storage.getItem(key)||'').includes('SYNTHETIC_PRIVATE_RESPONSE')))`), false);
  await evaluate(`window.confirm=window.fixtureConfirm;document.querySelector('[data-close]').click()`);
  results.push({ check: 'planner-recovery-unsaved-close-escape-lock-receipt-before-retry-and-no-private-browser-storage', submitCalls: fixture.state.submitCalls, extraDraftWritesOnRetry: fixture.state.patchCalls - patches, pass: true, scope: 'HTTP fixtures only, not PostgreSQL or authenticated E2E' });

  fixture.state.submission = null;
  fixture.state.patchDelay = 500;
  await navigate(base + '/student/agenda.html?grade=4&modo=api');
  await evaluate(`document.querySelector('[data-task]').click()`);
  await wait(`Boolean(document.querySelector('dialog[open] textarea'))`);
  const before = fixture.state.patchCalls;
  await evaluate(`const text=document.querySelector('dialog textarea');text.value='SYNTHETIC_LATE_RESPONSE';text.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('[data-save]').click()`);
  for (let i = 0; i < 100 && fixture.state.patchCalls === before; i++) await delay(20);
  assert.ok(fixture.state.patchCalls > before);
  await evaluate(`(async()=>{const auth=await import('/js/services/auth.service.js');void auth.signOut();return true})()`);
  await wait(`Boolean(document.querySelector('#learning-content [role="alert"]')) && !document.querySelector('#learning-content textarea')`);
  await delay(700);
  assert.equal(await evaluate(`document.querySelector('#learning-content').textContent.includes('SYNTHETIC_LATE_RESPONSE')`), false);
  assert.equal(await evaluate(`document.querySelectorAll('#learning-content dialog').length`), 0);
  fixture.state.patchDelay = 0;
  await navigate(base + '/student/agenda.html?grade=4&modo=api');
  fixture.state.denied = true;
  await evaluate(`document.querySelector('[data-task]').click()`);
  await wait(`Boolean(document.querySelector('#learning-content [role="alert"]'))`);
  assert.equal(await evaluate(`document.querySelectorAll('[data-task], #learning-content textarea').length`), 0);
  fixture.state.denied = false;
  results.push({ check: 'private-planner-logout-late-response-and-403-clear', pass: true, scope: 'Synthetic HTTP and session lifecycle only' });
};
